/// <summary>
///    Finds the specified record in the <c>AVAPriceSurchargeTable</c> table.
/// </summary>
/// <param name="_code">
///    The record ID of the <c>AVAPriceSurchargeTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceSurchargeTable</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceSurchargeTable find(   AVAPriceSurchargeCode   _code,
                                        boolean                 _forUpdate = false)
{
    AVAPriceSurchargeTable record;

    record.selectForUpdate(_forUpdate);

    if(_code)
    {
        select firstonly record
        index hint AVAPriceSurchargeTableIdx
        where record.AVAPriceSurchargeCode == _code;
    }

    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceSurchargeTable</c> table.
/// </summary>
/// <param name="_code">
///    The record ID of the <c>AVAPriceSurchargeTable</c> record to find.
/// </param>
/// <returns>
///    true if record in the <c>AVAPriceSurchargeTable</c> table exists
/// </returns>
public static boolean exist(AVAPriceSurchargeCode _code)
{
    return      _code
            &&  (   select firstonly AVAPriceSurchargeTable
                    index hint AVAPriceSurchargeTableIdx
                    where AVAPriceSurchargeTable.AVAPriceSurchargeCode == _code).Recid != 0;
}

/// <summary>
///    AVA <c>displayAVAPriceSurchargeLanguage</c> method.
/// </summary>
/// <param name="_languageId">
///    <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>Description</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Description displayAVAPriceSurchargeLanguage(LanguageId _languageId = CompanyInfo::languageId())
{
    Description retVal;

    retVal = AVAPriceSurchargeTranslation::findByAVAPriceSurchargeAndLanguage(this.RecId, _languageId).Description;

    if(!retVal)
    {
        retVal = this.AVAPriceSurchargeCode;
    }

    return retVal;
}

/// <summary>
/// method to show translation for Surcharge code
/// </summary>
/// <param name = "_surchargeCode">AVAPriceSurchargeCode</param>
/// <param name = "_languageId">LanguageId</param>
/// <returns>FreeTxt</returns>
static FreeTxt txt(AVAPriceSurchargeCode   _surchargeCode,
                   LanguageId             _languageId = CompanyInfo::languageId())
{
    AVAPriceSurchargeTable surchargeTable = AVAPriceSurchargeTable::find(_surchargeCode);
    LanguageTxt      languageTxt = LanguageTxt::find(surchargeTable.TableId,
                                                surchargeTable.RecId,
                                                _languageId);

    if (languageTxt.Txt)
    {
        return languageTxt.Txt;
    }

    if (surchargeTable.Description)
    {
        return surchargeTable.Description;
    }

    return surchargeTable.AVAPriceSurchargeCode;
}
